"""同じ8000投稿を順序交替で実行する。通常計時にbuild・test・profile解析を重ねない。"""
import json
from pathlib import Path
import subprocess
import sys
import time

p = Path(__file__).resolve().parent
root = p.parents[1]
setup = json.loads((p / 'setup.json').read_text())
rows = json.loads((p / 'trials.json').read_text()) if (p / 'trials.json').exists() else []
base = ['mise', 'exec', '--', 'python3', str(p / 'balanced120-probe.py'), '--memory', '4g', '--egress-bps', '80000000',
        '--waf', '--waf-posting-rate', '100000', '--waf-posting-concurrent', '256', '--waf-posting-client-rate', '1000',
        '--optional-log-stats', '--collect-server-log', '--posting-capacity-rate', '1600', '--posting-capacity-seconds', '5',
        '--posting-capacity-workers', '120', '--posting-capacity-threads', '16', '--posting-capacity-fixed-count']

def run(version, cpu, repeat, kind='fixed'):
    name = f'{kind}-{version}-r{repeat}-{cpu}cpu'
    if any(row['name'] == name for row in rows):
        return
    dest = p / (name + '.json')
    assert not dest.exists()
    command = base + ['--image', setup['images'][version]['id'], '--cpus', str(cpu), '--output', str(dest)]
    if kind == 'diagnostic':
        command += ['--collect-profiles']
    if kind == 'mixed':
        command.remove('--posting-capacity-fixed-count')
        for flag, value in [('--posting-capacity-rate', '160'), ('--posting-capacity-seconds', '60'), ('--egress-bps', '8000000000')]:
            command[command.index(flag) + 1] = value
        command += ['--posting-capacity-reads', '400', '--posting-capacity-subject-every', '4', '--posting-capacity-restart']
    print('START', name, flush=True)
    begin = time.monotonic()
    with (p / (name + '.log')).open('w') as log:
        result = subprocess.run(command, cwd=root, stdout=log, stderr=subprocess.STDOUT)
    row = {'name': name, 'version': version, 'cpu': cpu, 'repeat': repeat, 'kind': kind, 'command': command,
           'exit_code': result.returncode, 'wall_seconds': time.monotonic() - begin}
    if dest.exists():
        report = json.loads(dest.read_text())
        duration, count = report['duration_with_drain_seconds'], report['summary']['success']
        row.update({'throughput': count / duration, 'cpu_ms_per_success': report['resources']['cpu_cores_average'] * duration * 1000 / max(count, 1),
                    'summary': report['summary'], 'read_summary': report['read_summary'], 'integrity': report['integrity'],
                    'recovery': report['recovery'], 'resources': report['resources'], 'memory_peak_bytes': report['memory_peak_bytes']})
    rows.append(row)
    (p / 'trials.json').write_text(json.dumps(rows, indent=2))
    print('DONE', name, json.dumps({key: row.get(key) for key in ['exit_code', 'throughput', 'cpu_ms_per_success', 'summary']}), flush=True)
    assert result.returncode == 0 and row['integrity']['ok'] and not row['resources']['oom_kill_delta'] and row['recovery']['success'] == 100, name
    if kind == 'fixed':
        assert not row['summary']['errors'] and not row['summary']['skipped'], name

if sys.argv[1] == 'fixed':
    for repeat in [1, 2]:
        for cpu in [1, 2, 4]:
            for version in (['baseline', 'candidate'] if (repeat + cpu) % 2 == 0 else ['candidate', 'baseline']):
                run(version, cpu, repeat)
elif sys.argv[1] == 'diagnostic':
    for version in ['candidate-diag', 'baseline-diag']:
        run(version, 2, 1, 'diagnostic')
elif sys.argv[1] == 'mixed':
    for version in ['baseline', 'candidate']:
        run(version, 4, 1, 'mixed')
elif sys.argv[1] == 'extra':
    for version in ['candidate', 'baseline']:
        run(version, int(sys.argv[2]), int(sys.argv[3]))
else:
    raise ValueError(sys.argv[1])

